//! Replay of the original `UViewport::Exec` and its lock, unlock, drag, wire and input helpers.
//!
//! `fixtures/camera_exec.txt` was generated by `Build/camera_fixture_harness/camera_exec_harness.cpp`
//! from `UnCamera.cpp` at 69c3263. Each record builds the same fake object graph as the harness,
//! drives the Rust port (`camera_exec::{exec, lock, unlock, set_drag, is_wire, read_input}`), and
//! compares the recorded trace line by line with the fixture. Any camera service the replay does
//! not model panics (fail-fast).

use std::cell::{Cell, RefCell};
use std::collections::{BTreeMap, HashMap};
use std::ffi::c_void;
use std::mem::size_of;
use std::sync::OnceLock;

use hp2_abi::engine::generated::{APlayerPawn, UViewport};
use hp2_abi::{FColor, FPlane};
use hp2_engine::camera::CameraServices;
use hp2_engine::camera_exec::{exec, is_wire, lock, read_input, render_dev_exec, set_drag, unlock};
use hp2_engine::params::TChar;

const FIXTURE: &str = include_str!("fixtures/camera_exec.txt");
const EXPECTED_CASES: usize = 57;
const EXPECTED_FAMILIES: [(&str, usize); 6] = [
    ("exec", 35),
    ("lock", 5),
    ("unlock", 3),
    ("setdrag", 3),
    ("iswire", 8),
    ("readinput", 3),
];

// Non-dereferenced identity tokens for the C++ objects. Only their addresses are compared.
static SENT: [u8; 96] = [0; 96];
const AR_OFF: usize = 0;
const CONN_OFF: usize = 16;
const DRIVER_OFF: usize = 32;
const INPUT_OFF: usize = 48;
const RD_OFF: usize = 64;
const HITBUF_OFF: usize = 80;

/// `appUserDir()` as the harness returns it (`UserDir\`, trailing separator included).
static USER_DIR: OnceLock<Vec<TChar>> = OnceLock::new();

fn sentinel(off: usize) -> *mut c_void {
    SENT.as_ptr().wrapping_add(off) as *mut c_void
}

/// Per-case state read by the fakes. The trace is the replay output.
#[derive(Default)]
struct World {
    trace: Vec<String>,
    lcg: u32,
    size_x: i32,
    size_y: i32,
    rd: bool,
    detail: i32,
    nodes: i32,
    conn: i64,
    exist: i64,
    in_ret: i32,
    con_ret: i32,
    plr_ret: i32,
    /// Level actors: `Some(true)` is a hidden actor, `None` is a NULL entry.
    level: Vec<Option<bool>>,
    /// Backing store for `vp.snap_buff.data`.
    snap: Vec<FColor>,
}

thread_local! {
    static WORLD: RefCell<World> = RefCell::new(World::default());
    static SERVICES: Cell<*const CameraServices> = const { Cell::new(std::ptr::null()) };
}

fn emit(line: String) {
    WORLD.with(|w| w.borrow_mut().trace.push(line.trim_end().to_string()));
}

fn next_u32() -> u32 {
    WORLD.with(|w| {
        let mut w = w.borrow_mut();
        w.lcg = w.lcg.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        w.lcg
    })
}

/// Pixel seed per record: `0x2545F491 + 1000*family + idx`.
fn seed(family: u32, idx: usize) {
    let value = 0x2545_F491u32
        .wrapping_add(1000u32.wrapping_mul(family))
        .wrapping_add(idx as u32);
    WORLD.with(|w| w.borrow_mut().lcg = value);
}

fn family_code(family: &str) -> u32 {
    match family {
        "bitmap" => 1,
        "exec" => 2,
        "lock" => 3,
        "unlock" => 4,
        "setdrag" => 5,
        "iswire" => 6,
        "readinput" => 7,
        other => panic!("unknown camera_exec family {other}"),
    }
}

/// Harness `esc`: `\r` and `\n` as escapes, `"` as `'`, other non-printables as `?`.
fn esc(s: &str) -> String {
    s.chars()
        .map(|c| match c as u32 {
            0x0d => "\\r".to_string(),
            0x0a => "\\n".to_string(),
            0x22 => "'".to_string(),
            32..=126 => c.to_string(),
            _ => "?".to_string(),
        })
        .collect()
}

/// Reads a NUL-terminated TCHAR string.
///
/// # Safety
/// `p` must point to a NUL-terminated TCHAR string.
unsafe fn read_str(p: *const c_void) -> String {
    let mut q = p as *const TChar;
    let mut out = String::new();
    unsafe {
        while *q != 0 {
            out.push(char::from_u32(*q as u32).unwrap_or('?'));
            q = q.add(1);
        }
    }
    out
}

fn tchars(s: &str) -> Vec<TChar> {
    s.chars()
        .map(|c| c as u32 as TChar)
        .chain(std::iter::once(0))
        .collect()
}

fn is_blank(c: u32) -> bool {
    c == 0x20 || c == 0x09
}

fn is_alnum(c: u32) -> bool {
    (0x30..=0x39).contains(&c) || (0x41..=0x5a).contains(&c) || (0x61..=0x7a).contains(&c)
}

fn fold_case(c: u32) -> u32 {
    if (0x41..=0x5a).contains(&c) {
        c + 0x20
    } else {
        c
    }
}

/// Harness `ParseCommand`: a case-insensitive keyword at a word boundary; advances the cursor on match.
///
/// # Safety
/// `slot` must point to a valid `*const TChar` cursor; `token` to a NUL-terminated TCHAR string.
unsafe fn match_command(slot: *mut *const TChar, token: *const c_void) -> i32 {
    unsafe {
        let want: Vec<u32> = read_str(token).chars().map(|c| c as u32).collect();
        let mut p = *slot;
        while is_blank(*p as u32) {
            p = p.add(1);
        }
        let mut matched = true;
        for (i, &w) in want.iter().enumerate() {
            let c = *p.add(i) as u32;
            if c == 0 || fold_case(c) != fold_case(w) {
                matched = false;
                break;
            }
        }
        if !matched {
            return 0;
        }
        let end = p.add(want.len());
        if is_alnum(*end as u32) {
            return 0;
        }
        let mut q = end;
        while is_blank(*q as u32) {
            q = q.add(1);
        }
        *slot = q;
        1
    }
}

/// Harness `ParseToken` without escapes: a blank-delimited or quoted token, bounded by `max`.
///
/// # Safety
/// `slot` must point to a valid `*const TChar` cursor; `buf` must hold `max` TCHARs.
unsafe fn match_token(slot: *mut *const TChar, buf: *mut TChar, max: i32) -> i32 {
    unsafe {
        let max = max.max(0) as usize;
        let mut p = *slot;
        while is_blank(*p as u32) {
            p = p.add(1);
        }
        let mut len = 0usize;
        if *p as u32 == 0x22 {
            p = p.add(1);
            while *p != 0 && *p as u32 != 0x22 && len + 1 < max {
                *buf.add(len) = *p;
                len += 1;
                p = p.add(1);
            }
            if *p as u32 == 0x22 {
                p = p.add(1);
            }
        } else {
            while *p != 0 && !is_blank(*p as u32) {
                if len + 1 < max {
                    *buf.add(len) = *p;
                    len += 1;
                }
                p = p.add(1);
            }
        }
        if max > 0 {
            *buf.add(len) = 0;
        }
        *slot = p;
        (len != 0) as i32
    }
}

/// C `atoi`: leading blanks, optional sign, decimal digits; saturating.
fn c_atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
        i += 1;
    }
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let mut v: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        v = v.saturating_mul(10).saturating_add(i64::from(b[i] - b'0'));
        i += 1;
    }
    if neg {
        v = -v;
    }
    v.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32
}

/// Log destination label: the harness distinguishes AR, CONN and OUT archives.
fn label(ar: *mut c_void) -> &'static str {
    if ar == sentinel(AR_OFF) {
        "AR"
    } else if ar == sentinel(CONN_OFF) {
        "CONN"
    } else {
        "OUT"
    }
}

fn plane_bits(p: &FPlane) -> String {
    format!(
        "{:08x},{:08x},{:08x},{:08x}",
        p.x.to_bits(),
        p.y.to_bits(),
        p.z.to_bits(),
        p.w.to_bits()
    )
}

/// Bitmap archive: captures the serialized bytes, printed on delete.
struct Archive {
    path: String,
    bytes: Vec<u8>,
}

fn create_archive(path: &str) -> *mut c_void {
    let p = esc(path);
    emit(format!("  CREATE \"{p}\""));
    Box::into_raw(Box::new(Archive {
        path: p,
        bytes: Vec::new(),
    })) as *mut c_void
}

unsafe extern "C" fn unexpected_service() {
    panic!("camera_exec replay reached a camera service the fixture does not model");
}

unsafe extern "C" fn parse_command(cursor: *mut c_void, token: *const c_void) -> i32 {
    unsafe { match_command(cursor as *mut *const TChar, token) }
}

unsafe extern "C" fn parse_token(cursor: *mut c_void, buf: *mut c_void, len: i32) -> i32 {
    unsafe { match_token(cursor as *mut *const TChar, buf as *mut TChar, len) }
}

/// Harness `Parse(stream, match, &value)`: `appStrfind`, then `appAtoi` after the match.
unsafe extern "C" fn parse_int(
    stream: *const c_void,
    matched: *const c_void,
    value: *mut i32,
) -> i32 {
    unsafe {
        let s = read_str(stream);
        let m = read_str(matched);
        match s.find(m.as_str()) {
            Some(at) => {
                *value = c_atoi(&s[at + m.len()..]);
                1
            }
            None => 0,
        }
    }
}

unsafe extern "C" fn app_atoi(s: *const c_void) -> i32 {
    unsafe { c_atoi(&read_str(s)) }
}

unsafe extern "C" fn app_user_dir() -> *const c_void {
    USER_DIR.get_or_init(|| tchars("UserDir\\")).as_ptr() as *const c_void
}

/// `GFileManager->FileSize`: `Shot<n>` files below the `exist` knob report 54 bytes.
unsafe extern "C" fn file_size(path: *const c_void) -> i32 {
    unsafe {
        let p = esc(&read_str(path));
        let mut r = -1;
        if let Some(at) = p.find("Shot")
            && p.len() >= at + 8
        {
            let index = c_atoi(&p[at + 4..]);
            let exist = WORLD.with(|w| w.borrow().exist);
            if i64::from(index) < exist {
                r = 54;
            }
        }
        emit(format!("  FILESIZE \"{p}\" -> {r}"));
        r
    }
}

unsafe extern "C" fn create_file_writer(path: *const c_void) -> *mut c_void {
    unsafe { create_archive(&read_str(path)) }
}

/// `CreateFileWriter(SaveSlotPath * file)`: the harness sets `SaveSlotPath` to `Slot\`.
unsafe extern "C" fn create_slot_file_writer(file: *const c_void) -> *mut c_void {
    unsafe { create_archive(&format!("Slot\\/{}", read_str(file))) }
}

/// `CreateFileWriter(FString(appUserDir()) * file)`.
unsafe extern "C" fn create_user_dir_file_writer(file: *const c_void) -> *mut c_void {
    unsafe { create_archive(&format!("UserDir\\/{}", read_str(file))) }
}

unsafe extern "C" fn archive_serialize(ar: *mut c_void, data: *const c_void, count: i32) {
    unsafe {
        if count <= 0 {
            return;
        }
        let src = std::slice::from_raw_parts(data as *const u8, count as usize);
        (*(ar as *mut Archive)).bytes.extend_from_slice(src);
    }
}

unsafe extern "C" fn archive_delete(ar: *mut c_void) {
    unsafe {
        let arc = Box::from_raw(ar as *mut Archive);
        let hex: String = arc.bytes.iter().map(|b| format!("{b:02x}")).collect();
        emit(format!(
            "  FILE \"{}\" n={} {hex}",
            arc.path,
            arc.bytes.len()
        ));
    }
}

unsafe extern "C" fn log_format(ar: *mut c_void, fmt: *const c_void) {
    unsafe {
        let text = read_str(fmt);
        emit(format!("  LOG {} \"{}\"", label(ar), esc(&text)));
    }
}

unsafe extern "C" fn log_str(ar: *mut c_void, fmt: *const c_void, arg: *const c_void) {
    unsafe {
        let text = read_str(fmt).replacen("%s", &read_str(arg), 1);
        emit(format!("  LOG {} \"{}\"", label(ar), esc(&text)));
    }
}

unsafe extern "C" fn log_int(ar: *mut c_void, fmt: *const c_void, arg: i32) {
    unsafe {
        let text = read_str(fmt).replacen("%i", &arg.to_string(), 1);
        emit(format!("  LOG {} \"{}\"", label(ar), esc(&text)));
    }
}

unsafe extern "C" fn connection_logf_format(_conn: *mut c_void, fmt: *const c_void) {
    unsafe {
        emit(format!("  LOG CONN \"{}\"", esc(&read_str(fmt))));
    }
}

