/// `Actor->GetLevel()->NetDriver`: present for `conn >= 1`.
unsafe extern "C" fn viewport_net_driver(_viewport: *mut c_void) -> *mut c_void {
    if WORLD.with(|w| w.borrow().conn) >= 1 {
        sentinel(DRIVER_OFF)
    } else {
        std::ptr::null_mut()
    }
}

