unsafe extern "C" fn viewport_model_node_count(_viewport: *mut c_void) -> i32 {
    WORLD.with(|w| w.borrow().nodes)
}

unsafe extern "C" fn viewport_snap_buff_empty(viewport: *mut c_void) {
    unsafe {
        (*(viewport as *mut UViewport)).snap_buff.num = 0;
    }
}

unsafe extern "C" fn viewport_snap_buff_add(viewport: *mut c_void, count: i32) {
    unsafe {
        let n = count.max(0) as usize;
        let data = WORLD.with(|w| {
            let mut w = w.borrow_mut();
            w.snap.clear();
            w.snap.resize(
                n,
                FColor {
                    r: 0,
                    g: 0,
                    b: 0,
                    a: 0,
                },
            );
            w.snap.as_mut_ptr()
        });
        let view = &mut *(viewport as *mut UViewport);
        view.snap_buff.data = data as *mut c_void;
        view.snap_buff.num = count;
        view.snap_buff.max = count;
    }
}

unsafe extern "C" fn input_exec(_input: *mut c_void, cmd: *const c_void, _ar: *mut c_void) -> i32 {
    unsafe {
        let ret = WORLD.with(|w| w.borrow().in_ret);
        emit(format!("  INEXEC \"{}\" -> {ret}", esc(&read_str(cmd))));
        ret
    }
}

unsafe extern "C" fn input_read_input(_input: *mut c_void, delta: f32) {
    emit(format!("  INREAD delta={:08x} ar=OUT", delta.to_bits()));
}

/// Delegates to the Rust port, as the production C++ -> Rust wiring does.
unsafe extern "C" fn render_dev_exec_fake(
    rd: *mut c_void,
    cmd: *const c_void,
    ar: *mut c_void,
) -> i32 {
    unsafe {
        let svc = SERVICES.with(|c| c.get());
        assert!(!svc.is_null(), "services pointer is set before replay");
        render_dev_exec(&*svc, rd, cmd, ar)
    }
}

/// `RenDev->ReadPixels`: one LCG step per pixel, reset per record.
unsafe extern "C" fn render_dev_read_pixels(_rd: *mut c_void, dest: *mut c_void) {
    unsafe {
        let (w, h) = WORLD.with(|w| {
            let w = w.borrow();
            (w.size_x, w.size_y)
        });
        emit(format!("  READPIX {w}x{h}"));
        let out = dest as *mut FColor;
        for i in 0..(w * h) as usize {
            let v = next_u32();
            out.add(i).write(FColor {
                r: (v & 255) as u8,
                g: ((v >> 8) & 255) as u8,
                b: ((v >> 16) & 255) as u8,
                a: ((v >> 24) & 255) as u8,
            });
        }
    }
}

unsafe extern "C" fn render_dev_lock(
    _rd: *mut c_void,
    flash_scale: *const FPlane,
    flash_fog: *const FPlane,
    screen_clear: *const FPlane,
    flags: u32,
    hit_data: *mut c_void,
    hit_size: *mut i32,
) {
    unsafe {
        let flash = plane_bits(&*flash_scale);
        let fog = plane_bits(&*flash_fog);
        let clear = plane_bits(&*screen_clear);
        let size = if hit_size.is_null() { -1 } else { *hit_size };
        emit(format!(
            "  RDLOCK flash={flash} fog={fog} clear={clear} flags={flags} hit={} hitsize={size}",
            i32::from(!hit_data.is_null())
        ));
    }
}

unsafe extern "C" fn render_dev_unlock(_rd: *mut c_void, blit: i32) {
    emit(format!("  RDUNLOCK blit={blit}"));
}

unsafe extern "C" fn render_dev_detail_textures(_rd: *mut c_void) -> i32 {
    WORLD.with(|w| w.borrow().detail)
}

/// `DetailTextures ^= 1; SaveConfig();`
unsafe extern "C" fn render_dev_toggle_detail_textures(_rd: *mut c_void) {
    WORLD.with(|w| {
        let mut w = w.borrow_mut();
        w.detail ^= 1;
    });
    emit("  SAVECONFIG flags=16384".to_string());
}

fn services() -> CameraServices {
    const WORDS: usize = size_of::<CameraServices>() / size_of::<usize>();
    let filler = unexpected_service as unsafe extern "C" fn() as usize;
    let table: [usize; WORDS] = [filler; WORDS];
    // SAFETY: every field of `CameraServices` is a function pointer, so the table has the
    // struct's exact layout. Unused entries point at `unexpected_service`.
    let mut svc: CameraServices = unsafe { std::mem::transmute(table) };
    svc.parse_command = parse_command;
    svc.parse_token = parse_token;
    svc.parse_int = parse_int;
    svc.app_atoi = app_atoi;
    svc.app_user_dir = app_user_dir;
    svc.file_size = file_size;
    svc.create_file_writer = create_file_writer;
    svc.create_slot_file_writer = create_slot_file_writer;
    svc.create_user_dir_file_writer = create_user_dir_file_writer;
    svc.archive_serialize = archive_serialize;
    svc.archive_delete = archive_delete;
    svc.log_format = log_format;
    svc.log_str = log_str;
    svc.log_int = log_int;
    svc.connection_logf_format = connection_logf_format;
    svc.is_running = is_running;
    svc.viewport_stamp_current_time = viewport_stamp_current_time;
    svc.viewport_show_all_actors = viewport_show_all_actors;
    svc.viewport_update_input = viewport_update_input;
    svc.viewport_script_console_exec = viewport_script_console_exec;
    svc.viewport_player_exec = viewport_player_exec;
    svc.viewport_net_driver = viewport_net_driver;
    svc.net_driver_server_connection = net_driver_server_connection;
    svc.viewport_model_node_count = viewport_model_node_count;
    svc.viewport_snap_buff_empty = viewport_snap_buff_empty;
    svc.viewport_snap_buff_add = viewport_snap_buff_add;
    svc.input_exec = input_exec;
    svc.input_read_input = input_read_input;
    svc.render_dev_exec = render_dev_exec_fake;
    svc.render_dev_read_pixels = render_dev_read_pixels;
    svc.render_dev_lock = render_dev_lock;
    svc.render_dev_unlock = render_dev_unlock;
    svc.render_dev_detail_textures = render_dev_detail_textures;
    svc.render_dev_toggle_detail_textures = render_dev_toggle_detail_textures;
    svc
}

/// Harness `print_state`.
fn state_line(vp: &UViewport, pawn: &APlayerPawn) -> String {
    let (show, rend, hidden): (u32, i32, usize) = if vp.actor.is_null() {
        (0, -1, 0)
    } else {
        let hidden = WORLD.with(|w| {
            w.borrow()
                .level
                .iter()
                .filter(|a| **a == Some(true))
                .count()
        });
        (pawn.show_flags as u32, pawn.rend_map, hidden)
    };
    let detail = WORLD.with(|w| {
        let w = w.borrow();
        if w.rd { w.detail } else { -1 }
    });
    let n = vp.snap_buff.num;
    let fnv = if n > 0 {
        // SAFETY: the snap buffer holds `num` FColor entries backed by `World::snap`.
        let px =
            unsafe { std::slice::from_raw_parts(vp.snap_buff.data as *const FColor, n as usize) };
        px.iter()
            .flat_map(|c| [c.r, c.g, c.b, c.a])
            .fold(0x811c_9dc5u32, |h, b| {
                (h ^ u32::from(b)).wrapping_mul(16_777_619)
            })
    } else {
        0x811c_9dc5
    };
    format!(
        "  STATE show={show:08x} rend={rend} hidden={hidden} detail={detail} snap={}x{} n={n} fnv={fnv:08x} dragging={} hitsizes={} frame={} render={:08x} extra={:08x} hit={}",
        vp.snap_u,
        vp.snap_v,
        vp.dragging,
        vp.hit_sizes.num,
        vp.frame_count as u32,
        vp.render_flags,
        vp.extra_poly_flags,
        vp.hit_testing,
    )
}

/// Locks the render device with the harness's fixed planes.
fn lock_call(
    svc: &CameraServices,
    vp: *mut UViewport,
    flags: u32,
    hit: bool,
    hitsize: bool,
) -> i32 {
    let flash = FPlane {
        x: 0.3,
        y: 0.7,
        z: 0.11,
        w: 1.0,
    };
    let fog = FPlane {
        x: 0.05,
        y: 0.9,
        z: 0.25,
        w: 0.5,
    };
    let clear = FPlane {
        x: 0.2,
        y: 0.4,
        z: 0.6,
        w: 0.8,
    };
    let mut size: i32 = 5;
    let hit_data = if hit {
        sentinel(HITBUF_OFF)
    } else {
        std::ptr::null_mut()
    };
    let hit_size: *mut i32 = if hitsize {
        &mut size as *mut i32
    } else {
        std::ptr::null_mut()
    };
    unsafe { lock(svc, vp, &flash, &fog, &clear, flags, hit_data, hit_size) }
}

/// One parsed fixture record.
struct Case {
    family: String,
    idx: usize,
    kv: HashMap<String, String>,
    cmds: Vec<String>,
    expect: Vec<String>,
}

impl Case {
    fn num(&self, key: &str) -> i64 {
        let v = self
            .kv
            .get(key)
            .unwrap_or_else(|| panic!("case {} {} lacks {key}=", self.family, self.idx));
        v.parse().unwrap_or_else(|_| {
            panic!("case {} {} {key}={v} is not decimal", self.family, self.idx)
        })
    }

    fn hex(&self, key: &str) -> u32 {
        let v = self
            .kv
            .get(key)
            .unwrap_or_else(|| panic!("case {} {} lacks {key}=", self.family, self.idx));
        u32::from_str_radix(v, 16)
            .unwrap_or_else(|_| panic!("case {} {} {key}={v} is not hex", self.family, self.idx))
    }
}

fn parse_header(rest: &str) -> Case {
    let (head, cmds) = rest
        .split_once(" cmds=")
        .expect("camera_exec case header carries cmds=");
    let mut fields = head.split_whitespace();
    let family = fields.next().expect("case family").to_string();
    let idx = fields
        .next()
        .expect("case index")
        .parse::<usize>()
        .expect("case index is numeric");
    let kv: HashMap<String, String> = fields
        .map(|f| {
            let (k, v) = f.split_once('=').expect("knob is key=value");
            (k.to_string(), v.to_string())
        })
        .collect();
    let cmds = if cmds == "-" {
        Vec::new()
    } else {
        cmds.split('|').map(str::to_string).collect()
    };
    Case {
        family,
        idx,
        kv,
        cmds,
        expect: Vec::new(),
    }
}

fn parse_fixture() -> Vec<Case> {
    let mut out: Vec<Case> = Vec::new();
    for line in FIXTURE.lines() {
        if let Some(rest) = line.strip_prefix("case ") {
            out.push(parse_header(rest));
        } else if line.starts_with("  ") {
            let case = out.last_mut().expect("trace line before any case header");
            case.expect.push(line.trim_end().to_string());
        }
    }
    out
}

/// Replays one record and returns its trace.
fn replay(case: &Case) -> Vec<String> {
    let idx = case.idx;
    let family = case.family.as_str();
    let size_x = case.num("w") as i32;
    let size_y = case.num("h") as i32;
    let actor = case.num("actor") != 0;
    let rd = case.num("rd") != 0;

    WORLD.with(|w| {
        *w.borrow_mut() = World {
            size_x,
            size_y,
            rd,
            detail: case.num("detail") as i32,
            nodes: case.num("nodes") as i32,
            conn: case.num("conn"),
            exist: case.num("exist"),
            in_ret: case.num("in") as i32,
            con_ret: case.num("con") as i32,
            plr_ret: case.num("plr") as i32,
            level: if actor {
                vec![Some(true), None, Some(true)]
            } else {
                Vec::new()
            },
            ..World::default()
        };
    });
    seed(family_code(family), idx);

    let mut pawn: APlayerPawn = unsafe { std::mem::zeroed() };
    pawn.show_flags = case.num("show") as i32;
    pawn.rend_map = case.num("rend") as i32;
    let mut vp: UViewport = unsafe { std::mem::zeroed() };
    vp.size_x = size_x;
    vp.size_y = size_y;
    vp.dragging = case.num("prevdrag") as i32;
    if actor {
        vp.actor = &mut pawn as *mut APlayerPawn as *mut c_void;
    }
    if case.num("in") >= 0 {
        vp.input = sentinel(INPUT_OFF);
    }
    if rd {
        vp.ren_dev = sentinel(RD_OFF);
    }

    let svc = services();
    SERVICES.with(|c| c.set(&svc as *const CameraServices));
    let vp_ptr: *mut UViewport = &mut vp;

    match family {
        "exec" => {
            for cmd in &case.cmds {
                emit(format!("  CMD \"{cmd}\""));
                let buf = tchars(cmd);
                let r = unsafe {
                    exec(
                        &svc,
                        vp_ptr,
                        buf.as_ptr() as *const c_void,
                        sentinel(AR_OFF),
                    )
                }
                .unwrap_or_else(|fault| panic!("exec case {idx} faulted with {fault} on {cmd}"));
                emit(format!("  RET {r}"));
            }
        }
        "lock" => {
            let r = lock_call(
                &svc,
                vp_ptr,
                case.num("flags") as u32,
                case.num("hit") != 0,
                case.num("hitsize") != 0,
            );
            emit(format!("  RET {r}"));
        }
        "unlock" => {
            if idx == 2 {
                // The harness locks first with default knobs in unlock case 2.
                let r = lock_call(&svc, vp_ptr, 0, false, false);
                emit(format!("  RET {r}"));
            }
            unsafe { unlock(&svc, vp_ptr, case.num("blit") as i32) };
        }
        "setdrag" => {
            let r = unsafe { set_drag(&svc, vp_ptr, case.num("newdrag") as i32) };
            emit(format!("  RET {r}"));
        }
        "iswire" => {
            let r = unsafe { is_wire(&svc, vp_ptr) };
            emit(format!("  RET {r}"));
        }
        "readinput" => {
            let delta = f32::from_bits(case.hex("delta"));
            unsafe { read_input(&svc, vp_ptr, delta) };
        }
        other => panic!("unknown camera_exec family {other}"),
    }
    emit(state_line(&vp, &pawn));
    WORLD.with(|w| std::mem::take(&mut w.borrow_mut().trace))
}

#[test]
fn camera_exec_fixture_replays_bit_exact() {
    let cases = parse_fixture();
    assert_eq!(
        cases.len(),
        EXPECTED_CASES,
        "camera_exec.txt holds {EXPECTED_CASES} records"
    );
    let mut per_family: BTreeMap<&str, usize> = BTreeMap::new();
    let mut matched = 0usize;
    for case in &cases {
        let got = replay(case);
        assert_eq!(
            got, case.expect,
            "{} case {} diverged from the C++ fixture",
            case.family, case.idx
        );
        *per_family.entry(case.family.as_str()).or_insert(0) += 1;
        matched += 1;
    }
    assert_eq!(matched, EXPECTED_CASES, "every record matched");
    let expected: BTreeMap<&str, usize> = EXPECTED_FAMILIES.into_iter().collect();
    assert_eq!(per_family, expected, "per-family record counts");
}
